// GNU/Clang test-only link wrapper. The production implementation is unchanged.
// Prevent even GET_CAPS: closing that driver's descriptor resets the FPGA.
static unsigned fixtureCapabilityProbes = 0;
accelerator::Capabilities softwareFixtureProbe(const std::string& device)
    __asm__("__wrap__ZN9vibration11accelerator5probeERKNSt7__cxx1112basic_stringIcSt11char_traitsIcESaIcEEE");
accelerator::Capabilities softwareFixtureProbe(const std::string& device) {
    ++fixtureCapabilityProbes;
    accelerator::Capabilities result;
    result.device = device;
    result.reason = "disabled_in_software_workflow_fixture";
    return result;
}
