        for(unsigned c=0;c<4;++c){auto*bar=child<QProgressBar>(*pane,(QStringLiteral("detectionScore_")+keys[c]).toUtf8().constData());const double score=scores[int(c)].toDouble();check(bar->property("scoreAvailable").toBool()&&bar->property("modelScore").toDouble()==score&&bar->value()==int(std::lround(std::clamp(score,0.,100.)*10)),tag+QStringLiteral(" score bar preserves the original 0–100 model score"));check(child<QLabel>(*pane,(QStringLiteral("detectionScoreValue_")+keys[c]).toUtf8().constData())->text()==QString::number(score,'f',1),tag+QStringLiteral(" score number matches the original inference"));}
        auto*signal=child<QWidget>(*pane,"detectionSignalSummary");check(signal->property("hasSignal").toBool(),tag+QStringLiteral(" signal summary has a valid extracted window"));const auto rms=signal->property("acRmsAdc").toList(),volts=signal->property("acRmsVolts").toList(),crest=signal->property("crestFactors").toList(),kurtosis=signal->property("pearsonKurtosis").toList(),bands=signal->property("powerFractions").toList();check(rms.size()==3&&volts.size()==3&&signal->property("displayAdcRangeUv").toInt()==query->header.adc_range_uv&&crest.size()==3&&kurtosis.size()==3&&bands.size()==21,tag+QStringLiteral(" signal summary contains all three channels and the record voltage range"));for(unsigned c=0;c<3;++c){check(volts[int(c)].toDouble()==rms[int(c)].toDouble()*query->header.adc_range_uv/32768./1000000.,tag+QStringLiteral(" visible volts convert raw RMS using the record range only"));check(std::abs(std::log1p(rms[int(c)].toDouble())-features[int(c*21)].toDouble())<1e-12&&crest[int(c)].toDouble()==features[int(c*21+1)].toDouble()&&kurtosis[int(c)].toDouble()==features[int(c*21+2)].toDouble(),tag+QStringLiteral(" time features are exact read-only window values"));for(unsigned b=0;b<7;++b)check(bands[int(c*7+b)].toDouble()==features[int(c*21+3+b)].toDouble(),tag+QStringLiteral(" frequency bars are exact window fractions"));}
        QJsonObject bounds;for(const auto id:{"detectionResultCard","detectionScoresCard","detectionSignalSummary","detectionProfileSummary","candidateMechanicalConfirmed","openReferenceLibrary","openCandidateDetails","openCandidateModelSettings"}){auto*control=child<QWidget>(*pane,id);const QRect rectangle(control->mapTo(&window,QPoint()),control->size());check(control->isVisible()&&window.rect().contains(rectangle),tag+QStringLiteral(" dashboard control fits: ")+id);bounds.insert(id,QJsonArray{rectangle.x(),rectangle.y(),rectangle.width(),rectangle.height()});}
